#!/usr/bin/env bash
# DASHBOARD : colonne « Supprimer » (corbeille rouge) dans les 12 listes d'entités.
#   - features/admin/common/delete/ : ConfirmDeleteDialog (il faut TAPER « supprimer <nom> », collage
#     refusé, conséquences rappelées, erreur du serveur affichée), DeleteRowButton, deleteColumn
#     (colonne pour react-ts-tab-lib) ;
#   - listes : actualités, flash info, catégories, disciplines, familles, origines, cours, événements,
#     stages, galeries, membres, groupes. Le clic sur la corbeille n'ouvre pas la fiche de la ligne.
#   - corbeille grisée : galerie du carrousel d'accueil, et son propre compte dans « Membres ».
#   - les refus du serveur (ex. discipline encore utilisée par des cours) s'affichent dans la fenêtre.
# Usage (racine du repo) : bash apply-admin-delete-column.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if grep -qF "Supprimer définitivement" "apps/web/src/features/admin/common/delete/ConfirmDeleteDialog.tsx" 2>/dev/null; then echo "Déjà appliqué."; exit 0; fi
MODIFIED=("apps/web/src/app/(admin)/dashboard/categories/page.tsx" "apps/web/src/app/(admin)/dashboard/courses/page.tsx" "apps/web/src/app/(admin)/dashboard/events/page.tsx" "apps/web/src/app/(admin)/dashboard/posts/page.tsx" "apps/web/src/features/admin/breaking-news/components/BreakingNewsTable.tsx" "apps/web/src/features/admin/discipline-families/components/DisciplineFamiliesTable.tsx" "apps/web/src/features/admin/disciplines/components/DisciplinesTable.tsx" "apps/web/src/features/admin/galleries/components/GalleriesTable.tsx" "apps/web/src/features/admin/groups/components/GroupsTable.tsx" "apps/web/src/features/admin/origins/components/OriginsTable.tsx" "apps/web/src/features/admin/seminars/components/SeminarsTable.tsx" "apps/web/src/features/admin/users/components/UsersTable.tsx")
CREATED=("apps/web/src/features/admin/common/delete/ConfirmDeleteDialog.tsx" "apps/web/src/features/admin/common/delete/DeleteRowButton.tsx" "apps/web/src/features/admin/common/delete/deleteColumn.tsx" "apps/web/src/features/admin/common/delete/index.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/src/features/admin/common/delete" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/common/delete"
base64 -d > "apps/web/src/features/admin/common/delete/ConfirmDeleteDialog.tsx" <<'B64'
